22	      <path d="M6.50033 1.66699H13.5003C16.167 1.66699 18.3337 3.83366 18.3337 6.50033V13.5003C18.3337 14.7822 17.8244 16.0116 16.918 16.918C16.0116 17.8244 14.7822 18.3337 13.5003 18.3337H6.50033C3.83366 18.3337 1.66699 16.167 1.66699 13.5003V6.50033C1.66699 5.21845 2.17622 3.98907 3.08264 3.08264C3.98907 2.17622 5.21845 1.66699 6.50033 1.66699ZM6.33366 3.33366C5.53801 3.33366 4.77495 3.64973 4.21234 4.21234C3.64973 4.77495 3.33366 5.53801 3.33366 6.33366V13.667C3.33366 15.3253 4.67533 16.667 6.33366 16.667H13.667C14.4626 16.667 15.2257 16.3509 15.7883 15.7883C16.3509 15.2257 16.667 14.4626 16.667 13.667V6.33366C16.667 4.67533 15.3253 3.33366 13.667 3.33366H6.33366ZM14.3753 4.58366C14.6516 4.58366 14.9165 4.69341 15.1119 4.88876C15.3072 5.08411 15.417 5.34906 15.417 5.62533C15.417 5.90159 15.3072 6.16654 15.1119 6.3619C14.9165 6.55725 14.6516 6.66699 14.3753 6.66699C14.0991 6.66699 13.8341 6.55725 13.6388 6.3619C13.4434 6.16654 13.3337 5.90159 13.3337 5.62533C13.3337 5.34906 13.4434 5.08411 13.6388 4.88876C13.8341 4.69341 14.0991 4.58366 14.3753 4.58366ZM10.0003 5.83366C11.1054 5.83366 12.1652 6.27265 12.9466 7.05405C13.728 7.83545 14.167 8.89526 14.167 10.0003C14.167 11.1054 13.728 12.1652 12.9466 12.9466C12.1652 13.728 11.1054 14.167 10.0003 14.167C8.89526 14.167 7.83545 13.728 7.05405 12.9466C6.27265 12.1652 5.83366 11.1054 5.83366 10.0003C5.83366 8.89526 6.27265 7.83545 7.05405 7.05405C7.83545 6.27265 8.89526 5.83366 10.0003 5.83366ZM10.0003 7.50033C9.33728 7.50033 8.7014 7.76372 8.23256 8.23256C7.76372 8.7014 7.50033 9.33728 7.50033 10.0003C7.50033 10.6634 7.76372 11.2993 8.23256 11.7681C8.7014 12.2369 9.33728 12.5003 10.0003 12.5003C10.6634 12.5003 11.2993 12.2369 11.7681 11.7681C12.2369 11.2993 12.5003 10.6634 12.5003 10.0003C12.5003 9.33728 12.2369 8.7014 11.7681 8.23256C11.2993 7.76372 10.6634 7.50033 10.0003 7.50033Z" fill="white" />
