59	// ─── Newsletter form ──────────────────────────────────────────────────────────
60	
61	function FooterNewsletter() {
62	  const [email, setEmail] = useState("");
63	  const [status, setStatus] = useState<"idle" | "success" | "error">("idle");
64	  const [submitting, setSubmitting] = useState(false);
65	
66	  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
67	    e.preventDefault();
68	    if (!email) return;
69	    setSubmitting(true);
70	    try {
71	      await new Promise<void>((resolve) => setTimeout(resolve, 800));
72	      setStatus("success");
73	      setEmail("");
74	    } catch {
75	      setStatus("error");
76	    } finally {
77	      setSubmitting(false);
78	    }
79	  }
80	
81	  return (
82	    <div className={styles['footer-newsletter-card']}>
83	      <div className={styles['footer-newsletter-title']}>
84	        {/* "Join 500+ Subscribers" pill */}
85	        <div className={styles['news-subhead-out']}>
86	          <div className={styles['newsubott']}>
87	            <Image
88	              src="/images/webflow/Layer_1-57.svg"
89	              alt=""
90	              aria-hidden="true"
91	              width={14}
92	              height={14}
93	              className={styles['icon-regular']}
94	            />
95	            <p className={styles['news-pill-text']}>
96	              <strong className={styles['news-pill-highlight']}>Join 500+ Subscribers</strong>
97	            </p>
98	          </div>
99	        </div>
100	
101	        {/* Heading */}
102	        <h2 className={styles['heading-2-news']}>
103	          Agency Growth Insights{" "}
104	          <span className={styles['gradient-span']}>
105	            <br />
106	            Delivered Monthly
107	          </span>
108	        </h2>
109	
110	        {/* Sub-text */}
111	        <p className={styles['paragraph-small-4-gray']}>
112	          Smart growth strategies, CRM playbooks, industry trends, early product
113	          updates, and member-only offers — designed for modern agencies.
114	        </p>
115	      </div>
116	
117	      {/* Form block */}
118	      <div className={styles['footer-newsletter-form-block']}>
119	        {status === "success" ? (
120	          <div className={styles['success-message']}>
121	            Thank you! Your submission has been received!
122	          </div>
123	        ) : (
124	          <form onSubmit={handleSubmit} aria-label="Newsletter subscription">
125	            <div className={styles['column-tiny-2']}>
126	              <label htmlFor="Email-Footer-Newsletter" className="sr-only">
127	                Email address
128	              </label>
129	              <input
130	                type="email"
131	                name="Email-Footer-Newsletter"
132	                id="Email-Footer-Newsletter"
133	                placeholder="Enter your email"
134	                required
135	                aria-required="true"
136	                value={email}
137	                onChange={(e) => setEmail(e.target.value)}
138	                className={styles['text-field-small']}
139	              />
140	              <button
141	                type="submit"
142	                disabled={submitting}
143	                className={styles['button-secondary-small']}
144	              >
145	                {submitting ? "Please wait..." : "Get Started"}
146	              </button>
147	            </div>
148	            {status === "error" && (
149	              <div className={styles['error-message']} role="alert">
150	                Oops! Something went wrong while submitting the form.
151	              </div>
152	            )}
153	          </form>
154	        )}
155	      </div>
156	
157	      {/* Privacy line */}
158	      <div className={styles['newsletter-btm-line']}>
159	        <Image
160	          src="/images/webflow/Vector-24.svg"
161	          alt=""
162	          aria-hidden="true"
163	          width={14}
164	          height={14}
165	          className={styles['shield-icon']}
166	        />
167	        <p className={styles['news-btm-para']}>
168	          100% privacy guaranteed. Unsubscribe anytime.
169	        </p>
170	      </div>
171	    </div>
172	  );
173	}
174	
175	// ─── Footer link columns ──────────────────────────────────────────────────────
176	
177	type FooterLink = {
178	  label: string;
179	  href: string;
180	  external?: boolean;
181	  comingSoon?: boolean;
182	};
183	
184	const footerLinks: Record<string, FooterLink[]> = {
185	  About: [
186	    { label: "Our Mission", href: "/our-mission" },
187	    { label: "How It Works", href: "/how-it-works" },
188	    { label: "Portfolio", href: "/our-works" },
189	    { label: "Pricing", href: "/pricing" },
190	  ],
191	  Services: [
192	    { label: "Web Development", href: "/services/website-development" },
193	    { label: "UI UX Design", href: "#", comingSoon: true },
194	    { label: "Graphics Design", href: "#", comingSoon: true },
195	  ],
196	  Resources: [
197	    { label: "Blog", href: "/blog" },
198	    { label: "Affiliate", href: "#", comingSoon: true },
199	    { label: "Careers", href: "/careers" },
200	  ],
201	  Help: [
202	    { label: "Contact us", href: "/contact" },
203	    { label: "Help center", href: "https://help.boldteq.com", external: true },
204	    { label: "Terms of Service", href: "/terms-of-service" },
205	    { label: "Privacy Policy", href: "/privacy-policy" },
206	  ],
207	};
208	
209	
210	function FooterLinkColumn({ title, links }: { title: string; links: FooterLink[] }) {
211	  return (
212	    <div className={styles['column-x-large']}>
213	      <div className={styles['footer-title']}>{title}</div>
214	      <div className={styles['column-regular-2']}>
215	        {links.map((link) => {
216	          if (link.comingSoon) {
217	            /* Webflow: <div class="coming-soon-out">
218	                          <a class="footer-link disabled">Label</a>
219	                          <p class="coming-soon-badge">Coming Soon</p>
220	                        </div> */
221	            return (
222	              <div key={link.label} className={styles['coming-soon-out']}>
223	                <span className={`${styles['footer-link']} ${styles['disabled']}`}>
224	                  {link.label}
225	                </span>
226	                <span className={styles['coming-soon-badge']}>Coming Soon</span>
227	              </div>
228	            );
229	          }
230	
231	          if (link.external) {
232	            return (
233	              <a
234	                key={link.label}
235	                href={link.href}
236	                target="_blank"
237	                rel="noopener noreferrer"
238	                className={styles['footer-link']}
239	              >
240	                {link.label}
241	              </a>
242	            );
243	          }
244	
245	          return (
246	            <Link
247	              key={link.label}
248	              href={link.href}
249	              className={styles['footer-link']}
250	            >
251	              {link.label}
252	            </Link>
253	          );
254	        })}
255	      </div>
256	    </div>
257	  );
258	}
259	
260	// ─── Social links data ────────────────────────────────────────────────────────
261	
262	const socialLinks = [
263	  {
264	    icon: LinkedInIcon,
265	    href: SITE_CONFIG.social.linkedin,
266	    label: "Boldteq on LinkedIn",
267	  },
268	  {
269	    icon: InstagramIcon,
270	    href: SITE_CONFIG.social.instagram,
271	    label: "Boldteq on Instagram",
272	  },
273	  {
274	    icon: FacebookIcon,
275	    href: "https://www.facebook.com/people/Boldteq-Global-Pvt-Ltd/100070645008632/",
276	    label: "Boldteq on Facebook",
277	  },
278	];
279	
280	// ─── Main Footer export ───────────────────────────────────────────────────────
281	
282	export function Footer() {
283	  return (
284	    <footer className={styles['footer']} aria-label="Site footer">
285	      <div className={styles['container-large-6']}>
286	        <div className={styles['column-x-large']}>
287	          {/* Two-column grid: newsletter | right side */}
288	          <div className={styles['footer-grid']}>
289	            {/* Left: newsletter */}
290	            <div className={styles['footer-main']}>
291	              <FooterNewsletter />
292	            </div>
293	
294	            {/* Right: logo + social + links */}
295	            <div className={styles['footer-right']}>
296	              {/* Logo + social row */}
297	              <div className={styles['footer-heading']}>
298	                <div className={styles['footer-column']}>
299	                  <Link href="/" aria-label="Boldteq — go to homepage" className={styles['footer-logo']}>
300	                    <Image
301	                      src="/images/webflow/f-new.svg"
302	                      alt="Boldteq logo"
303	                      width={120}
304	                      height={36}
305	                      className={styles['footer-logo-img']}
306	                    />
307	                  </Link>
308	                </div>
309	
310	                {/* Social icons */}
311	                <div className={styles['row-regular']}>
312	                  {socialLinks.map(({ icon: Icon, href, label }) => (
313	                    <SocialLink key={label} href={href} label={label}>
314	                      <Icon />
315	                    </SocialLink>
316	                  ))}
317	                </div>
318	              </div>
319	
320	              {/* 4-column links grid */}
321	              <div className={styles['footer-links-grid']}>
322	                {Object.entries(footerLinks).map(([title, links]) => (
323	                  <FooterLinkColumn key={title} title={title} links={links} />
324	                ))}
325	              </div>
326	            </div>
327	          </div>
328	
329	          {/* Legal / copyright */}
330	          <div className={styles['footer-legal-wrapper']}>
331	            <div className={styles['copyright-outer']}>
332	              <div className={styles['copyright-text']}>
333	                Designed with ❤️ from India
334	              </div>
335	              <Image
336	                src="/images/webflow/🇮🇳.svg"
337	                alt="Indian National flag icon"
338	                width={18}
339	                height={18}
340	                className={styles['indian-flag']}
341	                onError={() => undefined}
342	              />
343	            </div>
344	          </div>
345	        </div>
