1	"use client";
2	
3	import Link from "next/link";
4	import Image from "next/image";
5	import { useState, useEffect } from "react";
6	import { NAV_ITEMS, CTA_NAV } from "@/lib/constants/navigation";
7	import type { NavItem } from "@/types/navigation";
8	import styles from "./mobile-nav.module.css";
9	
10	/*
11	  Webflow mobile nav: full-screen overlay matching .nav-23-menu at max-width 767px.
12	  Background: #082753, flex column, padding 10px 4%, z-index via --z-modal token.
13	  Nav links: color #fff, border-bottom 1px solid rgba(255,255,255,0.04), padding 12px 0.
14	  Dropdown chevron: color #21cfff.
15	*/
16	
17	function ChevronDownIcon({ rotated }: { rotated: boolean }) {
18	  return (
19	    <svg
20	      xmlns="http://www.w3.org/2000/svg"
21	      width="16"
22	      height="16"
23	      viewBox="0 0 24 24"
24	      fill="none"
25	      className={`${styles.chevron}${rotated ? ` ${styles.chevronRotated}` : ""}`}
26	      aria-hidden="true"
27	    >
28	      <path
29	        d="M11.9997 13.1714L16.9495 8.22168L18.3637 9.63589L11.9997 15.9999L5.63574 9.63589L7.04996 8.22168L11.9997 13.1714Z"
30	        fill="currentColor"
31	      />
32	    </svg>
33	  );
34	}
35	
36	function MobileNavGroup({
37	  item,
38	  onNavigate,
39	}: {
40	  item: NavItem;
41	  onNavigate: () => void;
42	}) {
43	  const [expanded, setExpanded] = useState(false);
44	  const submenuId = `mobile-submenu-${item.label.toLowerCase().replace(/\s+/g, "-")}`;
45	
46	  if (!item.children) {
47	    return (
48	      <Link
49	        href={item.href}
50	        onClick={onNavigate}
51	        className={styles.navLink}
52	      >
53	        {item.label}
54	      </Link>
55	    );
56	  }
57	
58	  return (
59	    <div className={styles.navRow}>
60	      <button
61	        type="button"
62	        onClick={() => setExpanded(!expanded)}
63	        aria-expanded={expanded}
64	        aria-haspopup="true"
65	        aria-controls={submenuId}
66	        className={styles.dropdownToggle}
67	      >
68	        {item.label}
69	        <ChevronDownIcon rotated={expanded} />
70	      </button>
71	
72	      {expanded && (
73	        <div id={submenuId} className={styles.submenu}>
74	          {item.children.map((child) => {
75	            const comingSoonBadge = child.comingSoon ? (
76	              <span className={styles.comingSoonBadge}>Coming Soon</span>
77	            ) : null;
78	
79	            const innerContent = (
80	              <span className={styles.submenuInner}>
81	                <span className={styles.submenuLabel}>{child.label}</span>
82	                {comingSoonBadge}
83	              </span>
84	            );
85	
86	            if (child.comingSoon) {
87	              return (
88	                <div
89	                  key={child.label}
90	                  className={`${styles.submenuItem} ${styles.submenuItemDisabled}`}
91	                >
92	                  {innerContent}
93	                </div>
94	              );
95	            }
96	
97	            if (child.external) {
98	              return (
99	                <a
100	                  key={child.label}
101	                  href={child.href}
102	                  target="_blank"
103	                  rel="noopener noreferrer"
104	                  onClick={onNavigate}
105	                  className={styles.submenuItem}
106	                >
107	                  {innerContent}
108	                </a>
109	              );
110	            }
111	
112	            return (
113	              <Link
114	                key={child.label}
115	                href={child.href}
116	                onClick={onNavigate}
117	                className={styles.submenuItem}
118	              >
119	                {innerContent}
120	              </Link>
121	            );
122	          })}
123	        </div>
124	      )}
125	    </div>
126	  );
127	}
128	
129	export function MobileNav({
130	  open,
131	  onClose,
132	}: {
133	  open: boolean;
134	  onClose: () => void;
135	}) {
136	  // Lock body scroll when open
137	  useEffect(() => {
138	    if (open) {
139	      document.body.style.overflow = "hidden";
140	    } else {
141	      document.body.style.overflow = "";
142	    }
143	    return () => {
144	      document.body.style.overflow = "";
145	    };
146	  }, [open]);
147	
148	  // Escape key closes the menu
149	  useEffect(() => {
150	    if (!open) return;
151	    function handleKey(e: KeyboardEvent) {
152	      if (e.key === "Escape") onClose();
153	    }
154	    document.addEventListener("keydown", handleKey);
155	    return () => document.removeEventListener("keydown", handleKey);
156	  }, [open, onClose]);
157	
158	  if (!open) return null;
159	
160	  return (
161	    <div
162	      id="mobile-nav"
163	      role="dialog"
164	      aria-modal="true"
165	      aria-label="Navigation menu"
166	      className={styles.overlay}
167	    >
168	      {/* Header — logo + close button */}
169	      <div className={styles.header}>
170	        <Link href="/" onClick={onClose} aria-label="Boldteq Home">
171	          <Image
172	            src="/images/webflow/Group-46895.svg"
173	            alt="Boldteq logo"
174	            width={130}
175	            height={40}
176	            className={styles.logoImage}
177	          />
178	        </Link>
179	        <button
180	          type="button"
181	          onClick={onClose}
182	          aria-label="Close navigation menu"
183	          className={styles.closeButton}
184	        >
185	          &#x2715;
186	        </button>
187	      </div>
188	
189	      {/* Nav links */}
190	      <div className={styles.navList}>
191	        {NAV_ITEMS.map((item) => (
192	          <MobileNavGroup
193	            key={item.label}
194	            item={item}
195	            onNavigate={onClose}
196	          />
197	        ))}
198	      </div>
199	
200	      {/* CTA buttons at bottom */}
201	      <div className={styles.ctaFooter}>
202	        <a
203	          href={CTA_NAV[0].href}
204	          target="_blank"
205	          rel="noopener noreferrer"
206	          onClick={onClose}
207	          className={styles.ctaLogin}
208	        >
209	          {CTA_NAV[0].label}
210	        </a>
211	
212	        <Link
